function makeCounter(c){let n=c;return function(c){return n+=c,n}}const c1=makeCounter(0),c2=makeCounter(100);function makeAccumulatorFactory(){return function(){const c=[];return function(n){return c.push(n),c.reduce(function(c,n){return c+n},0)}}}print("c1:",c1(1),c1(2),c1(3)),print("c2:",c2(-10),c2(-20)),print("c1 unaffected by c2:",c1(0));const acc=makeAccumulatorFactory()();print("acc:",acc(5),acc(10),acc(-3));